const callPanel=$('#callPanel'),localVideo=$('#localVideo'),remoteVideo=$('#remoteVideo'),callStatus=$('#callStatus'),incomingCall=$('#incomingCall');let localStream,pc,pending=[],calling=false;const rtc={iceServers:[{urls:'stun:stun.l.google.com:19302'}]},signal=(e,d={})=>socket.emit(e,{...d,chatId:activeChat});function media(){if(localStream)return Promise.resolve(localStream);return navigator.mediaDevices.getUserMedia({video:true,audio:true}).then(s=>(localStream=s,localVideo.srcObject=s,s))}function close(send){if(send&&activeChat)signal('call-ended');pc?.close();pc=null;pending=[];remoteVideo.srcObject=null;callPanel.hidden=true;calling=false;localStream?.getTracks().forEach(t=>t.stop());localStream=null;if(incomingCall.open)incomingCall.close()}function peer(){if(pc)return pc;pc=new RTCPeerConnection(rtc);localStream.getTracks().forEach(t=>pc.addTrack(t,localStream));pc.ontrack=e=>{remoteVideo.srcObject=e.streams[0];callStatus.textContent='Connected';calling=true};pc.onicecandidate=e=>e.candidate&&signal('webrtc-ice',{candidate:e.candidate});return pc}async function call(){if(!current()||current().members.length!==2)return toast('Video calls are for direct chats.');try{await media();callPanel.hidden=false;callStatus.textContent='Calling…';signal('call-invite')}catch{toast('Camera permission was not granted.')}}$('#cameraButton').onclick=async()=>{try{await media();callPanel.hidden=false;callStatus.textContent='Camera preview'}catch{toast('Could not start camera.')}};$('#videoCallButton').onclick=call;$('#endCall').onclick=()=>close(true);$('#cameraToggle').onclick=()=>{let t=localStream?.getVideoTracks()[0];if(t)t.enabled=!t.enabled};$('#muteToggle').onclick=()=>{let t=localStream?.getAudioTracks()[0];if(t)t.enabled=!t.enabled};socket.on('call-invite',d=>{$('#incomingCaller').textContent=`${d.name||'Someone'} is calling`;window.incomingId=d.chatId;incomingCall.showModal()});$('#declineCall').onclick=()=>{signal('call-declined');incomingCall.close()};$('#acceptCall').onclick=async()=>{try{if(activeChat!==window.incomingId)choose(window.incomingId);await media();callPanel.hidden=false;incomingCall.close();signal('call-accepted')}catch{signal('call-declined')}};socket.on('call-accepted',async()=>{if(!localStream)return;let p=peer(),o=await p.createOffer();await p.setLocalDescription(o);signal('webrtc-offer',{offer:p.localDescription})});socket.on('webrtc-offer',async d=>{try{await media();callPanel.hidden=false;let p=peer();await p.setRemoteDescription(d.offer);for(let c of pending)await p.addIceCandidate(c);pending=[];let a=await p.createAnswer();await p.setLocalDescription(a);signal('webrtc-answer',{answer:p.localDescription})}catch{close(true)}});socket.on('webrtc-answer',d=>pc?.setRemoteDescription(d.answer));socket.on('webrtc-ice',d=>pc?.remoteDescription?pc.addIceCandidate(d.candidate):pending.push(d.candidate));socket.on('call-declined',()=>{toast('The call was declined.');close()});socket.on('call-ended',()=>{toast('The call ended.');close()});window.addEventListener('beforeunload',()=>close(true));
